#include "physics/mean_simulation.h"
#include <fstream>
#include <iostream>
#include <nlohmann/json.hpp>
#include <stdexcept>
using json=nlohmann::json;
int main(int argc,char**argv){if(argc!=6)return 2;try{json fixture;std::ifstream(argv[4])>>fixture;slam::MeanSimulation s(argv[1],argv[2],argv[3]);json cases=json::array();
 for(unsigned repeat=0;repeat<2;++repeat){s.set_retail_minigame(true);s.reset();s.set_continuous_play(true);s.set_endless_play(false);unsigned tick=0,nudges=0,armed_tick=0,saved_tick=0;json events=json::array();
  for(auto&r:fixture.at("actions_rle"))for(unsigned i=0;i<r.at("ticks").get<unsigned>();++i){unsigned a=r.at("actions");auto letters=s.kick_letters();unsigned groups=s.material5_groups(),saves=s.kickback_consumptions(),ball=s.ball_number();bool armed=s.kickback_armed();s.set_launch(a&8);s.set_flippers(a&1,a&2);if(a&4)s.press_plunger();if(a&16){s.nudge(1,false);++nudges;}if(a&64){s.nudge(-1,false);++nudges;}if(a&32){s.nudge(0,true);++nudges;}if(!s.step())throw std::runtime_error(s.status());s.take_audio_requests();++tick;
   if(s.kick_letters()!=letters)events.push_back({{"event","letters"},{"tick",tick},{"before",letters},{"after",s.kick_letters()},{"ball",s.ball_number()}});
   if(s.material5_groups()>groups){if(!s.kickback_armed()||s.kick_letters()!=std::array<std::uint8_t,4>{})throw std::runtime_error("KICK group did not arm/clear letters");armed_tick=tick;events.push_back({{"event","armed"},{"tick",tick},{"callback",s.material5_display_callback()},{"ball",s.ball_number()}});}
   if(s.kickback_consumptions()>saves){if(!armed_tick||!armed||s.kickback_armed()||s.ball_number()!=ball||s.kickback_timer()<249||s.kickback_timer()>250)throw std::runtime_error("KICK save consumed wrong state");if(s.material5_display_callback()!=0x411710)throw std::runtime_error("Kickback display request missing");bool physical_save=false;unsigned saved_index=8;for(unsigned k=0;k<s.ball_count();++k){const auto&b=s.ball(k);if((b.i32(0)>>16)==12&&(b.i32(4)>>16)==518&&b.i32(0x14)==0&&b.i32(0x18)==-0x34000){physical_save=true;saved_index=k;}}if(!physical_save||saved_index!=3)throw std::runtime_error("Saved pool ball position/impulse differs");saved_tick=tick;json pool=json::array();for(unsigned k=0;k<8;++k)pool.push_back({{"index",k},{"x",s.ball(k).i32(0)},{"y",s.ball(k).i32(4)},{"vx",s.ball(k).i32(0x14)},{"vy",s.ball(k).i32(0x18)}});events.push_back({{"event","saved"},{"saved_pool_index",saved_index},{"pool",pool},{"tick",tick},{"timer",s.kickback_timer()},{"callback",s.material5_display_callback()},{"ball",s.ball_number()}});}
  }
  if(armed_tick!=30261||saved_tick!=30280||s.kickback_consumptions()!=1||s.material5_groups()!=1||s.tilted())throw std::runtime_error("Natural KICK/save chain incomplete");
  s.set_launch(true);s.set_flippers(false,false);unsigned bonus=s.bonus_completions();bool expired=false;while(!s.game_over()&&tick<150000){if(!s.step()&&!s.game_over())throw std::runtime_error(s.status());s.take_audio_requests();++tick;if(!expired&&s.kickback_timer()<0){if(tick!=31280)throw std::runtime_error("Kickback grace expiry differs");expired=true;events.push_back({{"event","timer_expired"},{"tick",tick}});}if(s.bonus_completions()!=bonus){bonus=s.bonus_completions();events.push_back({{"event","bonus"},{"tick",tick},{"ball",s.ball_number()},{"score",s.score()},{"armed",s.kickback_armed()},{"timer",s.kickback_timer()}});}}
  if(tick!=39224||s.score()!=397952580||nudges!=9||bonus!=4)throw std::runtime_error("Kickback finite reference differs score="+std::to_string(s.score())+" tick="+std::to_string(tick));if(!s.game_over()||s.ball_count()||!expired||bonus<3)throw std::runtime_error("Kickback finite lifecycle incomplete");const auto score=s.score();const auto raw=s.shared_raw_state().fields;auto saves=s.kickback_consumptions();for(unsigned i=0;i<64;++i){s.press_plunger();s.set_flippers(true,true);if(s.step()||s.score()!=score||s.shared_raw_state().fields!=raw||s.kickback_consumptions()!=saves)throw std::runtime_error("Kickback GameOver changed");}s.reset();if(s.game_over()||s.score()||s.kickback_armed()||s.kickback_consumptions()||s.material5_groups()||s.kick_letters()!=std::array<std::uint8_t,4>{})throw std::runtime_error("Kickback newgame reset differs");cases.push_back({{"events",events},{"final_tick",tick},{"final_score",score},{"bonus_completions",bonus},{"nudges",nudges},{"consumptions",saves}});
 }
 if(cases[0]!=cases[1])throw std::runtime_error("Kickback fixture nondeterministic");std::ofstream(argv[5])<<json({{"scope","Two fresh native legal-key KICK arming/leftsave/timer expiry/finite GameOver/freeze/reset chains; no field injection or fullOriginaltrajectory claim"},{"cases",cases}}).dump(2)<<'\n';std::cout<<"PASS two natural KICK/save/expiry/GameOver/reset chains\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
